export const CityScene = () => {
    const { scene:scene_city_1 } = useGLTF(getResourcePrefix() + '/test_scene/Choose.glb')

    const { city_obj_descs, city_obj_transformation } = useMemo(() => {
        let city_objs = [];
        for (let i = 0; i < scene_city_1.children[1].children.length; ++i) {
          const child = scene_city_1.children[1].children[i];
          city_objs.push(child);
        }
        let city_obj_descs = [];
        let city_obj_transformation = new Map();
        for (let i = 0; i < city_objs.length; ++i) {
          // if not found match
          let detectDuplicateIdx = -1;
          const city_obj = city_objs[i];
          for (var j = 0; j < city_obj_descs.length; ++j) {
            const test_city_obj = city_obj_descs[j];
            if (test_city_obj.children.length === city_obj.children.length) {
              let bbNotMatch = false;
              for (var k = 0; k < test_city_obj.children.length; ++k) {
                // console.log(test_city_obj.children[k].geometry.boundingBox, city_obj.children[k].geometry.boundingBox, test_city_obj.children[k].geometry.boundingBox.equals(city_obj.children[k].geometry.boundingBox));
                if (!test_city_obj.children[k].geometry.boundingBox.equals(city_obj.children[k].geometry.boundingBox)) {
                  bbNotMatch = true;
                  break;
                }
              }
              if (!bbNotMatch) {
                detectDuplicateIdx = j;
              }
            }
            if (detectDuplicateIdx >= 0) {
              break;
            }
          }
          if (detectDuplicateIdx < 0) {
            city_obj_transformation[city_obj_descs.length] = [city_obj.matrixWorld];
            city_obj_descs.push(city_obj);
          } else {
            city_obj_transformation[detectDuplicateIdx].push(city_obj.matrixWorld);
          }
        }
        return { city_obj_descs, city_obj_transformation };
      }, [scene_city_1]);

      const body_baseTexture = useLoader(THREE.TextureLoader, getResourcePrefix() + '/test_model/texture0_tex_bdy_00_base1.png');
      const body_segm_2 = useLoader(THREE.TextureLoader, getResourcePrefix() + '/test_model/tex_bdy_1009_00_SkinArea.png');
      const body_diffMap = useLoader(THREE.TextureLoader, getResourcePrefix() + '/test_model/texture1_tex_bdy_00_diff1.png');
      const body_ZOffsetIntensity = useLoader(THREE.TextureLoader, getResourcePrefix() + '/test_model/tex_bdy1009_00_OutlineZOffsetIntensity.png');
      body_segm_2.colorSpace = THREE.SRGBColorSpace;
      body_baseTexture.colorSpace = THREE.SRGBColorSpace;
      body_diffMap.colorSpace = THREE.SRGBColorSpace;
    

    let customInstanceMeshObjs = useMemo(() => {
        let instanceMeshObjs = [];
        city_obj_descs.forEach((city_obj_desc, i) => {
            city_obj_desc.children.forEach((children_mesh, j) => {
                let diffuseMap = body_diffMap;
                if (children_mesh.material.map) {
                    diffuseMap = children_mesh.material.map;
                }
                instanceMeshObjs.push(new CustomInstancedMesh(children_mesh.geometry, 
                    new CustomMaterial(), 
                    new CustomParameter({
                    baseTexture: body_baseTexture, 
                    diffMap: diffuseMap,
                    segMap: body_baseTexture, 
                    segMap_2: body_segm_2, 
                    segMap_3: body_baseTexture, 
                    outlineZOffsetIntensityMap: body_ZOffsetIntensity,
                defines: { USE_BASE_MAP: '1', 
                                UNKNOWN_DEFINE_3: '',
                                UNKNOWN_DEFINE_FS_6: '',
              
                                // For outline
                                UNKNOWN_DEFINE_7: '',
                                UNKNOWN_DEFINE_FS_12: '',
              
                              }
                      }),"test_instance",
                      city_obj_transformation[i].length
                ));
                for (let k = 0; k < city_obj_transformation[i].length; ++k) {
                    instanceMeshObjs[instanceMeshObjs.length - 1].setMatrixAt(k, city_obj_transformation[i][k]);
                }
            });
        });
        return instanceMeshObjs;
    }, [city_obj_descs, city_obj_transformation, body_baseTexture, body_segm_2, body_diffMap, body_ZOffsetIntensity]);
    return (
        <>
            {customInstanceMeshObjs ? customInstanceMeshObjs.map((customInstanceMeshObj, i) => {
                return <primitive 
                    object={customInstanceMeshObj} key={i}
                />;
            }):null}
        </>
    );

}